entries[17624] = { ["name"] = "Versteinerung", ["text"] = "Sofort\nIhr werdet zu Stein und seid 1 Min. lang gegen alle körperlichen Angriffe und Zauber geschützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein." }
