entries[17626] = { ["name"] = "Fläschchen der Titanen", ["text"] = "Sofort\nErhöht die maximale Gesundheit des Spielers 2 Stunden lang um 1200. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an." }
