entries[17628] = { ["name"] = "Oberste Macht", ["text"] = "Sofort 1 sek. Abklingzeit\nErhöht die Schadenswirkung von Zaubern und magischen Effekten 2 Stunden lang um bis zu 150. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an." }
entries[17629] = { ["name"] = "Chromatischer Widerstand", ["text"] = "Sofort\nErhöht Euren Widerstand gegen alle Arten von Magie 2 Stunden lang um 25. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an und ist mit allen anderen widerstandssteigernden Zaubern und Gegenständen stapelbar." }
