entries[17632] = { ["name"] = "Alchimistenstein", ["text"] = "Wirken in 1 min\nReagenzien:\nEssenz des Feuers (8), Essenz der Erde (8), Essenz der Luft (8), Essenz des Wassers (8), Essenz des Lebens (8), Schwarzes Vitriol (2), Schwarzer Lotus (4)\nAlchimistenstein\nWird beim Aufheben gebunden\nEinzigartigSchmuck\n+8 Willenskraft\nBenötigt Alchimie\n(300)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 33%." }
