entries[18545] = { ["name"] = "Skorpidstich", ["text"] = "10 Mana 5 - 30 Meter Reichweite\nBenötigt Distanzwaffe\nSticht einen Feind und verringert 20 Sek. lang Stärke und Beweglichkeit des Ziels um 1." }
