entries[18559] = { ["name"] = "Dämonenhacke", ["text"] = "5 Meter Reichweite\nWirken in 5 sek.\nDämonenhacke zur Zerstörung des Dämonenkristalls." }
entries[18560] = { ["name"] = "Mondstoff", ["text"] = "Wirken in 1 min 4 tagen Abklingzeit\nReagenzien:\nTeufelsstoff (2)\nDie Läuterung und Verwandlung von besudeltem Teufelsstoff in Mondstoff kann nur an einem Mondbrunnen durchgeführt werden. Zudem werden es die Wasser nur hin und wieder gestatten, auf diese Weise benutzt zu werden." }
entries[18561] = { ["name"] = "Schießen", ["text"] = "5 - 30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nSchießt auf den Feind und fügt körperlichen Schaden zu." }
entries[18562] = { ["name"] = "Rasche Heilung", ["text"] = "20% von Grundmana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\n[ S03 - Tuning and Overrides Passive - Druide : Heilt ein Ziel mit einem aktiven Effekt von 'Verjüngung' oder 'Nachwachsen' sofort / Verbraucht bei einem verbündeten Ziel einen Effekt von 'Verjüngung' oder 'Nachwachsen' und heilt es sofort] um einen Betrag, der 12 Sek. 'Verjüngung' beziehungsweise 18 Sek. 'Nachwachsen' entspricht." }
